def child_ready(_):
    if workflow.elements("login_user"):
        return "login"
    if "#!/credentials" in driver.current_url:
        return False
    keys = ("group", app.get("context_ready"))
    if any(key and key in app["selectors"] and workflow.elements(key)
           for key in keys):
        return "ready"
    return False

try:
    state = WebDriverWait(driver, 5).until(child_ready)
    login_required = state == "login"
except TimeoutException:
    login_required = False
